import numpy as np
import base64

def gen_sine(freq, sr=44100, duration=0.5, volume=0.5):
    t = np.arange(int(sr * duration)) / sr
    s = np.sin(2 * np.pi * freq * t)
    return (s * volume * 32767).astype(np.int16)

def gen_saw(freq, sr=44100, duration=0.5, volume=0.5):
    t = np.arange(int(sr * duration)) / sr
    phase = (t * freq) % 1
    s = 2 * phase - 1
    return (s * volume * 32767).astype(np.int16)

def gen_noise(sr=44100, duration=0.2, volume=0.5):
    s = np.random.randn(int(sr * duration))
    return (s * volume * 32767).astype(np.int16)

bass = gen_sine(55, duration=0.5, volume=0.8)
lead = gen_saw(220, duration=0.3, volume=0.7)
drum = gen_noise(duration=0.2, volume=0.9)

def to_b64(arr):
    return base64.b64encode(arr.tobytes()).decode('ascii')

print("BASS:", to_b64(bass))
print("LEAD:", to_b64(lead))
print("DRUM:", to_b64(drum))
EOF"}

