import json
import subprocess

with open('/workspace/pattern.json', 'r') as f:
    pattern = json.load(f)

# Set all cells
for row, row_data in enumerate(pattern):
    for ch, cell in row_data.items():
        if cell:
            note = cell.get("note", "")
            instrument = cell.get("instrument", 0)

            # Convert note format from C-4 to C4 (tracker expects C4 not C-4)
            if note:
                note = note.replace('-', '')

            cmd = ['ft2', 'call', 'pattern_set_cell', json.dumps({
                "pattern": 0,
                "row": row,
                "channel": ch,
                "note": note,
                "instrument": instrument
            })]
            result = subprocess.run(cmd, capture_output=True, text=True)
            if result.returncode != 0:
                print(f"Error at row {row}, ch {ch}: {result.stderr}")

print("Pattern cells set")
EOF"}

