{"command": "python3 << 'EOF'
import subprocess
import json

# Pattern data: row -> {channel: {note, instrument}}
pattern_cells = {}

# Bass line (channel 1): A(33), C(24), D(26), E(28) repeated every 16 rows
bass_notes = [33]*16 + [24]*16 + [26]*16 + [28]*16
for row, note_num in enumerate(bass_notes):
    if row not in pattern_cells:
        pattern_cells[row] = {}
    # Convert note number to tracker format (C0=0, so 24=C2, 33=F2, 37=A2)
    note_names = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B']
    octave = note_num // 12
    note_name = note_names[note_num % 12]
    pattern_cells[row][1] = {"note": f"{note_name}{octave}", "instrument": 1}

# Melody (channel 0)
melody = [
    (0, 57), (4, 57), (8, 57), (12, 57),   # A4
    (16, 52), (20, 52), (24, 52), (28, 52), # F4
    (32, 55), (36, 55), (40, 55), (44, 55), # G4
    (48, 59), (52, 59), (56, 59), (60, 59), # A4
]
for row, note_num in melody:
    if row not in pattern_cells:
        pattern_cells[row] = {}
    note_names = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B']
    octave = note_num // 12
    note_name = note_names[note_num % 12]
    pattern_cells[row][0] = {"note": f"{note_name}{octave}", "instrument": 2}

# Drums (channel 2): Kick every 4 rows
for row in range(0, 64, 4):
    if row not in pattern_cells:
        pattern_cells[row] = {}
    pattern_cells[row][2] = {"note": "C0", "instrument": 3}

# Set all cells
for row, channels in pattern_cells.items():
    for ch, cell in channels.items():
        cmd = ['ft2', 'call', 'pattern_set_cell', json.dumps({
            "pattern": 0,
            "row": row,
            "channel": ch,
            "note": cell["note"],
            "instrument": cell["instrument"]
        })]
        result = subprocess.run(cmd, capture_output=True, text=True)
        if "error" in result.stderr.lower() or result.returncode != 0:
            print(f"Error at row {row}, ch {ch}: {result.stderr}")

print(f"Set {len(pattern_cells)} rows with data")
EOF"}

